import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BZO4qERu.js";const d=JSON.parse('{"title":"Справочник","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/index.md","filePath":"ru/guides/index.md","lastUpdated":1792323081000}'),s={name:"ru/guides/index.md"};function l(n,t,i,h,m,g){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="справочник" tabindex="-1">Справочник <a class="header-anchor" href="#справочник" aria-label="Permalink to &quot;Справочник&quot;">​</a></h1><p>Добро пожаловать в справочник Memoh. Здесь собрано всё, что нужно для настройки и использования Memoh, — в трёх разделах.</p><h2 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h2><p>Начните отсюда, если вы впервые работаете с Memoh. Узнайте, как установить приложение, создать первого Bot, подключить канал и освоить повседневные основы.</p><ul><li><strong><a href="./overview.html">Обзор</a></strong>: что такое Memoh и как его части складываются вместе.</li><li><strong><a href="./quick-start.html">Быстрый старт</a></strong>: установите приложение, войдите, создайте первого Bot, поручите ему настоящую работу и подключите чат-платформу.</li><li><strong><a href="./working-with-bots.html">Работа с Bot</a></strong>: что делегировать, как формулировать запрос, когда разделять Bot — плюс полный справочник конфигурации по вкладкам.</li><li><strong><a href="./sessions.html">Сессии</a></strong>: разберитесь в сессиях chat и discuss, маршрутизации и панелях статуса.</li><li><strong><a href="./files.html">Файлы</a></strong>: просматривайте и редактируйте файлы в рабочем пространстве Bot.</li><li><strong><a href="./slash-commands.html">Слэш-команды</a></strong>: командные сокращения для повседневного управления.</li><li><strong><a href="./../integrations/channels/">Каналы</a></strong>: подключите Memoh к Slack, Telegram, Feishu, Discord и другим платформам.</li></ul><h2 id="продвинутые-возможности" tabindex="-1">Продвинутые возможности <a class="header-anchor" href="#продвинутые-возможности" aria-label="Permalink to &quot;Продвинутые возможности&quot;">​</a></h2><p>Углубляйтесь, когда основы освоены. Эти страницы охватывают возможности, автоматизацию и внешних провайдеров.</p><ul><li><strong><a href="./extensions.html">Выбор расширения</a></strong>: навыки, hooks, MCP, коннекторы или Supermarket — к чему обращаться.</li><li><strong><a href="./acp.html">Agents / ACP</a></strong>: стройте мультиагентные рабочие процессы и взаимодействуйте с Agent Client Protocol.</li><li><strong><a href="./approvals.html">Подтверждения и доверие</a></strong>: к чему Bot может прикасаться, когда он спрашивает вас и что держать за подтверждением.</li><li><strong><a href="./access.html">Контроль доступа</a></strong>: настройте ACL-пресеты, режимы доступа и правила с заданной областью действия.</li><li><strong><a href="./container.html">Рабочее пространство</a></strong>: как устроено рабочее пространство с точки зрения интерфейса продукта.</li><li><strong><a href="./browser-computer-use.html">Browser / Computer Use</a></strong>: работайте с браузерами с графическим интерфейсом (headed) и сессиями видимого рабочего стола.</li><li><strong><a href="./skills.html">Навыки</a></strong> и <strong><a href="./supermarket.html">Supermarket</a></strong>: добавляйте переиспользуемые промпт-модули и шаблоны из каталога.</li><li><strong><a href="./../self-hosted/connectors.html">Коннекторы</a></strong>: подключайте сторонние сервисы, такие как GitHub и Notion.</li><li><strong><a href="./hooks.html">Hooks</a></strong> и <strong><a href="./mcp.html">MCP</a></strong>: подключайте инструменты, правила автоматизации и внешние источники данных.</li><li><strong><a href="./memory.html">Долговременная память</a></strong>: управляйте долговременной памятью после настройки провайдера.</li><li><strong><a href="./compaction.html">Сжатие контекста</a></strong>: уменьшайте объём контекста активной сессии.</li><li><strong><a href="./schedule.html">Задачи по расписанию</a></strong>: запускайте регулярную работу по cron-расписанию.</li><li><strong><a href="./../integrations/providers/llm.html">Провайдеры моделей</a></strong>: провайдеры моделей и модели; провайдеры веб-поиска, видео, памяти и TTS находятся рядом в боковой панели.</li></ul><h2 id="сценарии-использования" tabindex="-1">Сценарии использования <a class="header-anchor" href="#сценарии-использования" aria-label="Permalink to &quot;Сценарии использования&quot;">​</a></h2><h2 id="где-получить-помощь" tabindex="-1">Где получить помощь <a class="header-anchor" href="#где-получить-помощь" aria-label="Permalink to &quot;Где получить помощь&quot;">​</a></h2><p>Эти страницы — справочник по продукту. Тарифы, кредиты и оплата, вопросы по аккаунту и прямая связь с командой Memoh — в <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">Центре помощи</a>.</p>',11)])])}const f=r(s,[["render",l]]);export{d as __pageData,f as default};
